re typical of distemper.\\"}\\n   ],\\n   \\"recommended_tests\\": [\\n       \\"Complete Blood Count (CBC) - to evaluate for signs of infection or inflammation\\",\\n       \\"Biochemical Profile - to assess liver and kidney function\\",\\n       \\"Imaging studies (CT or MRI) of the brain - to rule out structural causes of seizures\\",\\n       \\"Viral PCR tests - to confirm the presence of Canine Distemper virus or other viral pathogens\\",\\n       \\"Urine analysis - to evaluate for signs of urinary tract infection or kidney disease\\"\\n   ],\\n   \\"warning_signs\\": [\\n       \\"Increased severity or frequency of seizures\\",\\n       \\"Worsening of oculonasal discharge or onset of pneumonia-like symptoms\\",\\n       \\"Signs of gastrointestinal involvement such as vomiting or diarrhea\\",\\n       \\"Lethargy or depression\\",\\n       \\"Failure to respond to antibiotic therapy\\"\\n   ],\\n   \\"summary\\": \\"Big, a male Jack Russell Terrier of unknown age, presents with symptoms strongly indicative of Canine Distemper, including seizures, chorea, hard pad, and mucoid oculonasal discharge, following a fever that lasted five days. Immediate veterinary attention is crucial for diagnosis confirmation and appropriate management. Given the severity of the symptoms, hospitalization for supportive care and monitoring may be necessary.\\"\\n}"	2026-04-27 01:23:28.637+08	f	\N	40	26	\N	\N		[]			
