1	TOS	Terms of Service	Welcome to FMH Animal Clinic. By utilizing our veterinary services, you agree to the following terms and conditions. These terms are designed to ensure the highest standard of care for your pets and a clear understanding of our professional relationship.\r\n\r\n1. Veterinary Services\r\nFMH Animal Clinic provides professional veterinary medical care, including diagnostics, surgical procedures, and wellness treatments. While we strive for the best possible outcomes, medicine is not an exact science, and no guarantee can be made regarding the results of any treatment or procedure.\r\n\r\n2. Appointments and Cancellations\r\nArrival: Please arrive 10 minutes prior to your scheduled appointment to complete any necessary paperwork.\r\n\r\nCancellations: We require at least 24 hours' notice for cancellations or rescheduling.\r\n\r\nNo-Shows: Failure to arrive for an appointment without notice may result in a "No-Show" fee or the requirement of a non-refundable deposit for future bookings.\r\n\r\n3. Emergency Care\r\nFMH Animal Clinic operates during standard business hours. In the event of a life-threatening emergency outside of our operating hours, please contact the nearest 24-hour emergency veterinary hospital immediately.\r\n\r\n4. Financial Policy\r\nPayment: Payment is due in full at the time services are rendered. We accept [Cash, Credit Cards, Digital Payments, etc.].\r\n\r\nEstimates: We are happy to provide a written estimate for procedures or surgeries. Please note that estimates are approximations; final costs may vary based on the clinical needs of the patient during treatment.\r\n\r\nRefunds: Due to the nature of medical services and supplies, all sales of medications and clinical services are final.\r\n\r\n5. Patient Safety and Conduct\r\nFor the safety of all clients, staff, and patients:\r\n\r\nAll dogs must be on a leash and under control.\r\n\r\nAll cats and small exotic pets must be in an appropriate carrier.\r\n\r\nWe reserve the right to refuse service in cases of aggressive behavior or non-compliance with clinic safety protocols.\r\n\r\n6. Limitation of Liability\r\nFMH Animal Clinic and its staff shall not be held liable for any indirect, incidental, or consequential damages arising from the use of our services, except in cases of proven gross negligence.	2.1	t	2026-04-24 15:58:52.765+08	2026-04-11 01:50:59.535+08
2	PRIVACY	Privacy Policy	At FMH Animal Clinic, your privacy and the confidentiality of your petΓÇÖs medical records are of the utmost importance to us. This policy outlines how we collect, use, and protect your information.\r\n\r\n1. Information We Collect\r\nWe collect information necessary to provide veterinary care and maintain our business records, including:\r\n\r\nClient Information: Name, address, phone number, and email address.\r\n\r\nPatient Information: PetΓÇÖs name, breed, age, medical history, and vaccination records.\r\n\r\nFinancial Information: Payment details processed through secure encrypted systems.\r\n\r\n2. How We Use Your Information\r\nYour data is used specifically for:\r\n\r\nMaintaining accurate medical records for your pet.\r\n\r\nSending appointment reminders and health alerts (e.g., vaccination due dates).\r\n\r\nProcessing payments for services rendered.\r\n\r\nInternal quality control and clinic improvements.\r\n\r\n3. Information Sharing\r\nWe do not sell or rent your personal information to third parties. Information may only be shared under the following circumstances:\r\n\r\nReferrals: To specialist veterinarians or emergency clinics if your pet requires advanced care.\r\n\r\nDiagnostic Labs: To external laboratories for bloodwork or pathology.\r\n\r\nLegal Requirements: If required by law, such as reporting certain communicable diseases to local health or agricultural authorities.\r\n\r\nInsurance: Sharing records with pet insurance providers at your explicit request.\r\n\r\n4. Data Security\r\nWe implement industry-standard physical and digital security measures to protect your personal information and your petΓÇÖs medical files from unauthorized access or disclosure.\r\n\r\n5. Your Rights\r\nYou have the right to:\r\n\r\nRequest a copy of your petΓÇÖs medical records.\r\n\r\nUpdate or correct your contact information at any time.\r\n\r\nOpt out of non-essential communications (such as newsletters).\r\n\r\n6. Changes to This Policy\r\nFMH Animal Clinic reserves the right to update this Privacy Policy as needed. Any significant changes will be posted on our website or communicated to you during your next visit.	1.5	t	2026-04-24 15:58:52.781+08	2026-04-11 01:50:59.549+08
